breblanc etc…on fabrique aussi des cubes carrés de 3 x 3 cm avec hauteur variable, selon le modèle à concevoir, nous produisons sur mesures des carrés en marbre ou granite que l’on fait le montage sur son toile de différents dimensions"}$j$::jsonb, 'https://lechantier.ma/en/produits/materiaux-de-construction-autres/eclater-marbre') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
