INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('0b02d7ae-c497-540e-b095-c0a8321d6a14'::uuid, '802fb74b-4831-5e78-b5c5-cc0b04ef2e59'::uuid, 'Marbre Gris benslimane', 'Marbre Gris Benslimane, issu du Maroc, offre une teinte grise uniforme avec des nuances naturelles. Disponible en dalles 60×30, 60×60 cm, finition poli ou adouci.', 'Other', NULL, NULL, 380.0, 'MAD', 'm²', '50 Mètre', 'https://lechantier.ma/uploads/media/942f9f67b0d7.webp', $j$["https://lechantier.ma/uploads/media/942f9f67b0d7.webp", "https://lechantier.ma/uploads/media/7a78b2b79ce9.webp", "https://lechantier.ma/uploads/media/8c2b577566fa.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/materiaux-de-construction-autres/marbre-gris-benslimane", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Marbre marocain Gris Benslimane, couleur grise uniforme avec nuances naturelles. Disponible en dalles 60×30, 60×60 cm, épaisseur 2-3 cm. Finitions poli, adouci. Dureté élevée, idéal pour sols et murs.", "technical_specifications_original": "• Marbre marocain Gris Benslimane, couleur grise uniforme avec nuances naturelles. Disponible en dalles 60×30, 60×60 cm, épaisseur 2-3 cm. Finitions poli, adouci. Dureté élevée, idéal pour sols et murs.", "specs": "• Marbre marocain Gris Benslimane, couleur grise uniforme avec nuances naturelles. Disponible en dalles 60×30, 60×60 cm, épaisseur 2-3 cm. Finitions poli, adouci. Dureté élevée, idéal pour sols et murs."}$j$::jsonb, 'https://lechantier.ma/en/produits/materiaux-de-construction-autres/marbre-gris-benslimane') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.