INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('06a06049-8081-5e8d-a9e8-1e6bed016afb'::uuid, '802fb74b-4831-5e78-b5c5-cc0b04ef2e59'::uuid, 'Marbre Gris Tiflet', 'Marbre marocain au ton gris élégant, rehaussé de fines veines claires. Idéal pour sols, murs et finitions modernes ou classiques.', 'Other', NULL, NULL, 220.0, 'MAD', 'm²', '50 Mètre', 'https://lechantier.ma/uploads/media/446cca8cd0bd.webp', $j$["https://lechantier.ma/uploads/media/446cca8cd0bd.webp", "https://lechantier.ma/uploads/media/f4b3b2aa7dfb.webp", "https://lechantier.ma/uploads/media/729cad3fcc6f.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/materiaux-de-construction-autres/marbre-gris-tiflet", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Gris Tiflet – Marbre NaturelOrigine : MarocCouleur : Gris moyen à foncé, veines clairesFinition : Polie, adoucie, bouchardée (selon demande)Utilisation : Sols, murs, escaliers, plans de travail, façades intérieuresFormat : Dalles et tranches sur mesureAbsorption d’eau : ~0,3%Dureté : Bonne résistance à l’usure (Mohs ~3)Recommandé pour : Intérieur – résidentiel & commercial", "technical_specifications_original": "• Gris Tiflet – Marbre NaturelOrigine : MarocCouleur : Gris moyen à foncé, veines clairesFinition : Polie, adoucie, bouchardée (selon demande)Utilisation : Sols, murs, escaliers, plans de travail, façades intérieuresFormat : Dalles et tranches sur mesureAbsorption d’eau : ~0,3%Dureté : Bonne résistance à l’usure (Mohs ~3)Recommandé pour : Intérieur – résidentiel & commercial", "specs": "• Gris Tiflet – Marbre NaturelOrigine : MarocCouleur : Gris moyen à foncé, veines clairesFinition : Polie, adoucie, bouchardée (selon demande)Utilisation : Sols, murs, escaliers, plans de travail, façades intérieuresFormat : Dalles et tranches sur mesureAbsorption d’eau : ~0,3%Dureté : Bonne résistance à l’usure (Mohs ~3)Recommandé pour : Intérieur – résidentiel & commercial"}$j$::jsonb, 'https://lechantier.ma/en/produits/materiaux-de-construction-autres/marbre-gris-tiflet') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('f5cc21bc-1bf0-55bf-a076-f40191659bd5'::uuid, '802fb74b-4831-5e78-b5c5-cc0b04ef2e59'::uuid, 'Marbre noir Veiny', 'Marbre Noir Veiny, élégant et sophistiqué, associe un fond noir profond à des veines blanches lumineuses, apportant un contraste saisissant et un style contemporain à vos espaces.', 'Other', NULL, NULL, 450.0, 'MAD', 'm²', '50 Mètre', 'https://lechantier.ma/uploads/media/8beb79cf8974.webp', $j$["https://lechantier.ma/uploads/media/8beb79cf8974.webp", "https://lechantier.ma/uploads/media/fba99a39887b.webp", "https://lechantier.ma/uploads/media/da44a1788401.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/materiaux-de-construction-autres/marbre-noir-veiny", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Marbre Noir Veiny, noir intense avec veines blanches. Dalles 60×30, 60×60 cm, épaisseur 2-3 cm. Finitions poli, adouci. Résistant, idéal sols, murs et plans de travail.", "technical_specifications_original": "• Marbre Noir Veiny, noir intense avec veines blanches. Dalles 60×30, 60×60 cm, épaisseur 2-3 cm. Finitions poli, adouci. Résistant, idéal sols, murs et plans de travail.", "specs": "• Marbre Noir Veiny, noir intense avec veines blanches. Dalles 60×30, 60×60 cm, épaisseur 2-3 cm. Finitions poli, adouci. Résistant, idéal sols, murs et plans de travail."}$j$::jsonb, 'https://lechantier.ma/en/produits/materiaux-de-construction-autres/marbre-noir-veiny') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantit