INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('c9a6833a-d73c-56a3-9b95-1600f3b4c3b7'::uuid, '802fb74b-4831-5e78-b5c5-cc0b04ef2e59'::uuid, 'Marron Emperador', 'Marron Emperador est un marbre d''origine espagnole, reconnu pour ses riches tons brun et beige, rehaussés de veines claires élégantes, apportant chaleur et caractère à tout espace.', 'Other', NULL, NULL, 750.0, 'MAD', 'm²', '50 Mètre', 'https://lechantier.ma/uploads/media/4f3ff2b74aa6.webp', $j$["https://lechantier.ma/uploads/media/4f3ff2b74aa6.webp", "https://lechantier.ma/uploads/media/d719741ac634.webp", "https://lechantier.ma/uploads/media/aa63f499c6d9.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/materiaux-de-construction-autres/marron-emperador", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Marbre Marron Emperador, Espagne. Dalles 60×30, 60×60 cm, épaisseur 2-3 cm. Finitions poli, adouci. Bonne dureté, idéal pour sols, murs, plans de travail et salles de bain.", "technical_specifications_original": "• Marbre Marron Emperador, Espagne. Dalles 60×30, 60×60 cm, épaisseur 2-3 cm. Finitions poli, adouci. Bonne dureté, idéal pour sols, murs, plans de travail et salles de bain.", "specs": "• Marbre Marron Emperador, Espagne. Dalles 60×30, 60×60 cm, épaisseur 2-3 cm. Finitions poli, adouci. Bonne dureté, idéal pour sols, murs, plans de travail et salles de bain."}$j$::jsonb, 'https://lechantier.ma/en/produits/materiaux-de-construction-autres/marron-emperador') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.