INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('9ba27872-ac6a-5a82-9879-6defe5b2df2d'::uuid, '802fb74b-4831-5e78-b5c5-cc0b04ef2e59'::uuid, 'Onyx miel', 'L''onyx miel est une pierre semi-précieuse luxueuse, aux tons dorés et veinures translucides. Parfaite pour murs rétroéclairés et décors haut de gamme au style raffiné et unique.', 'Other', NULL, NULL, 4500.0, 'MAD', 'm²', '50 Mètre', 'https://lechantier.ma/uploads/media/c67e1bdb9032.webp', $j$["https://lechantier.ma/uploads/media/c67e1bdb9032.webp", "https://lechantier.ma/uploads/media/5b7e4507a983.webp", "https://lechantier.ma/uploads/media/90593487c92a.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/materiaux-de-construction-autres/onyx-miel", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• L’onyx miel est une pierre d’exception, prisée pour son élégance, sa transparence naturelle et son aspect luxueux, mais nécessite une pose délicate et une protection adaptée.Type de roche : Onyx (calcédoine / carbonate de calcium)Couleur : Miel, ambre, doré, avec veines blanches ou translucidesOrigine : Iran, Turquie, Pakistan, AfghanistanDensité : Environ 2.6 – 2.8 g/cm³Dureté (échelle de Mohs) : 3 – 4Résistance à la compression : Environ 100 – 150 MPaRésistance à la flexion : 10 – 20 MPaPorosité : Moyenne à élevéeTranslucidité : Élevée – peut être rétroéclairéFinitions : Polie (essentiellement), parfois adoucieUtilisations : Murs décoratifs, revêtements intérieurs, plans de vasque, mobilier, éléments rétroéclairés", "technical_specifications_original": "• L’onyx miel est une pierre d’exception, prisée pour son élégance, sa transparence naturelle et son aspect luxueux, mais nécessite une pose délicate et une protection adaptée.Type de roche : Onyx (calcédoine / carbonate de calcium)Couleur : Miel, ambre, doré, avec veines blanches ou translucidesOrigine : Iran, Turquie, Pakistan, AfghanistanDensité : Environ 2.6 – 2.8 g/cm³Dureté (échelle de Mohs) : 3 – 4Résistance à la compression : Environ 100 – 150 MPaRésistance à la flexion : 10 – 20 MPaPorosité : Moyenne à élevéeTranslucidité : Élevée – peut être rétroéclairéFinitions : Polie (essentiellement), parfois adoucieUtilisations : Murs décoratifs, revêtements intérieurs, plans de vasque, mobilier, éléments rétroéclairés", "specs": "• L’onyx miel est une pierre d’exception, prisée pour son élégance, sa transparence naturelle et son aspect luxueux, mais nécessite une pose délicate et une protection adaptée.Type de roche : Onyx (calcédoine / carbonate de calcium)Couleur : Miel, ambre, doré, avec veines blanches ou translucidesOrigine : Iran, Turquie, Pakistan, AfghanistanDensité : Environ 2.6 – 2.8 g/cm³Dureté (échelle de Mohs) : 3 – 4Résistance à la compression : Environ 100 – 150 MPaRésistance à la flexion : 10 – 20 MPaPorosité : Moyenne à élevéeTranslucidité : Élevée – peut être rétroéclairéFinitions : Polie (essentiellement), parfois adoucieUtilisations : Murs décoratifs, revêtements intérieurs, plans de vasque, mobilier, éléments rétroéclairés"}$j$::jsonb, 'https://lechantier.ma/en/produits/materiaux-de-construction-autres/onyx-miel') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('cf6d602c-0678-511b-adf7-d6e37d7bea1a'::uuid, '802fb74b-4831-5e78-b5c5-cc0b04ef2e59'::uuid, 'Pierre Taza Beige', 'La pierre Taza Beige est une roche naturelle marocaine à teinte beige douce, homogène et chaleureuse, idéale pour sols, murs et façades.', 'Other', NULL, NULL, 200.0, 'MAD', 'm²', '50 Mètre', 'https://lechantier.ma/uploads/media/0d2ea7b359ea.webp', $j$["https://lechantier.ma/uploads/media/0d2ea7b359ea.webp", "https://lechantier.ma/uploads/media/f75936efe69e.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/materiaux-de-construction-autres/pierre-taza-beige", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Origine : Maroc (région de Taza)Type de roche : CalcaireCouleur : Beige clair à beige doréDensité : Environ 2.4 – 2.6 g/cm³Porosité : Moyenne à élevéeRésistance à la compression : 70 – 100 MPaRésistance à la flexion : 8 – 12 MPaFinitions disponibles : Adoucie, bouchardée, sablée, flamméeUsages : Sols, murs, façades, dallages extérieurs, aménagements paysagers", "technical_specifications_original": "• Origine : Maroc (région de Taza)Type de roche : CalcaireCouleur : Beige clair à beige doréDensité : Environ 2.4 – 2.6 g/cm³Porosité : Moyenne à élevéeRésistance à la compression : 70 – 100 MPaRésistance à la flexion : 8 – 12 MPaFinitions disponibles : Adoucie, bouchardée, sablée, flamméeUsages : Sols, murs, façades, dallages extérieurs, aménagements paysagers", "specs": "• Origine : Maroc (région de Taza)Type de roche : CalcaireCouleur : Beige clair à beige doréDensité : Environ 2.4 – 2.6 g/cm³Porosité : Moyenne à élevéeRésistance à la compression : 70 – 100 MPaRésistance à la flexion : 8 – 12 MPaFinitions disponibles : Adoucie, bouchardée, sablée, flamméeUsages : Sols, murs, façades, dallages extérieurs, aménagements paysagers"}$j$::jsonb, 'https://lechantier.ma/en/produits/materiaux-de-construction-autres/pierre-taza-beige') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('7b6c8f2a-e968-5453-bcaf-6cb2c7b27d8f'::uuid, '802fb74b-4831-5e78-b5c5-cc0b04ef2e59'::uuid, 'Pierre taza gris', 'Le Taza Gris est un marbre marocain de couleur gris clair à gris moyen, avec une texture homogène et élégante. Apprécié pour son aspect sobre et moderne, il offre un aspect sobre.', 'Other', NULL, NULL, 200.0, 'MAD', 'm²', '50 Mètre', 'https://lechantier.ma/uploads/media/53da7a5b5824.webp', $j$["https://lechantier.ma/uploads/media/53da7a5b5824.webp", "https://lechantier.ma/uploads/media/a022990d0148.webp", "https://lechantier.ma/uploads/media/174aa12c0224.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/materiaux-de-construction-autres/pierre-taza-gris", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Origine : Maroc (région de Taza)Type de roche : Marbre calcaireCouleur : Gris clair à gris moyen, parfois avec de fines veines blanches ou beigeDensité : Environ 2.6 – 2.7 g/cm³Absorption d’eau : < 0.5 %Porosité : FaibleRésistance à la compression : Environ 120 – 150 MPaRésistance à la flexion : Environ 10 – 15 MPaFinitions disponibles : Polie, adoucie, bouchardée, flammée, sabléeUtilisations : Revêtement mural et sol, escaliers, façades, mobilier, plans de travail", "technical_specifications_original": "• Origine : Maroc (région de Taza)Type de roche : Marbre calcaireCouleur : Gris clair à gris moyen, parfois avec de fines veines blanches ou beigeDensité : Environ 2.6 – 2.7 g/cm³Absorption d’eau : < 0.5 %Porosité : FaibleRésistance à la compression : Environ 120 – 150 MPaRésistance à la flexion : Environ 10 – 15 MPaFinitions disponibles : Polie, adoucie, bouchardée, flammée, sabléeUtilisations : Revêtement mural et sol, escaliers, façades, mobilier, plans de travail", "specs": "• Origine : Maroc (région de Taza)Type de roche : Marbre calcaireCouleur : Gris clair à gris moyen, parfois avec de fines veines blanches ou beigeDensité : Environ 2.6 – 2.7 g/cm³Absorption d’eau : < 0.5 %Porosité : FaibleRésistance à la compression : Environ 120 – 150 MPaRésistance à la flexion : Environ 10 – 15 MPaFinitions disponibles : Polie, adoucie, bouchardée, flammée, sabléeUtilisations : Revêtement mural et sol, escaliers, façades, mobilier, plans de travail"}$j$::jsonb, 'https://lechantier.ma/en/produits/materiaux-de-construction-autres/pierre-taza-gris') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
