INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('243bc047-a240-5a72-b326-f7b57aa21f76'::uuid, '9346c29f-3ff9-5d74-9fdb-039cee3ef96d'::uuid, 'Tole en polyester G.O translucide', 'Tôle ondulée en polyester, légère et robuste, offrant une bonne résistance mécanique. Idéale pour toitures et bardages, facile à poser et durable.', 'Other', NULL, NULL, 65.0, 'MAD', 'm²', '1000 Mètre', 'https://lechantier.ma/uploads/media/093e5c4e0dfe.webp', $j$["https://lechantier.ma/uploads/media/093e5c4e0dfe.webp", "https://lechantier.ma/uploads/media/a44bc7c6ca3e.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/materiaux-de-construction-autres/tole-en-polyester-g-o-translucide", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Caractéristiques général :Largeur utile : 0,98 mLongueur : de 2 m à 8 mComposition : PolyesterCouleur : translucide Propriétés mécaniques et thermiques :Résistance à la traction : 70 N/mm² (ISO 527-4)Module d’élasticité à la traction : 2300 N/mm² (ISO 527-4)Allongement à la rupture : 1,5 % (ISO 527-4)Résistance à la flexion : 100 N/mm² (ISO 14125)Résistance thermique : 80 °CCoefficient de conductivité thermique (λ) : 0,21 W/mKPoids spécifique : 400 g/m² - 600 g/m²Avantages :Excellente résistance mécanique et longue durée de vieBonne résistance aux UV et aux conditions climatiques extrêmesLégère et facile à manipulerPossibilité de translucidité pour un éclairage naturelFacilité de découpe et de mise en œuvre", "technical_specifications_original": "• Caractéristiques général :Largeur utile : 0,98 mLongueur : de 2 m à 8 mComposition : PolyesterCouleur : translucide Propriétés mécaniques et thermiques :Résistance à la traction : 70 N/mm² (ISO 527-4)Module d’élasticité à la traction : 2300 N/mm² (ISO 527-4)Allongement à la rupture : 1,5 % (ISO 527-4)Résistance à la flexion : 100 N/mm² (ISO 14125)Résistance thermique : 80 °CCoefficient de conductivité thermique (λ) : 0,21 W/mKPoids spécifique : 400 g/m² - 600 g/m²Avantages :Excellente résistance mécanique et longue durée de vieBonne résistance aux UV et aux conditions climatiques extrêmesLégère et facile à manipulerPossibilité de translucidité pour un éclairage naturelFacilité de découpe et de mise en œuvre", "specs": "• Caractéristiques général :Largeur utile : 0,98 mLongueur : de 2 m à 8 mComposition : PolyesterCouleur : translucide Propriétés mécaniques et thermiques :Résistance à la traction : 70 N/mm² (ISO 527-4)Module d’élasticité à la traction : 2300 N/mm² (ISO 527-4)Allongement à la rupture : 1,5 % (ISO 527-4)Résistance à la flexion : 100 N/mm² (ISO 14125)Résistance thermique : 80 °CCoefficient de conductivité thermique (λ) : 0,21 W/mKPoids spécifique : 400 g/m² - 600 g/m²Avantages :Excellente résistance mécanique et longue durée de vieBonne résistance aux UV et aux conditions climatiques extrêmesLégère et facile à manipulerPossibilité de translucidité pour un éclairage naturelFacilité de découpe et de mise en œuvre"}$j$::jsonb, 'https://lechantier.ma/en/produits/materiaux-de-construction-autres/tole-en-polyester-g-o-translucide') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
