INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('074fc930-b4c4-50e2-8bbd-361a6fbc14ba'::uuid, '433c6235-ef86-54ef-885c-13b43dea1609'::uuid, 'Cadre spot aluminium', 'Spot LED : luminaire compact et moderne offrant un éclairage puissant et homogène. Disponible en différentes puissances, températures de couleur et angles d''ouverture. Idéal pour l''éclairage des plafonds, commerces, bureaux et espaces résidentiels.', 'Electrical supplies', 'Eclairage', NULL, 40.0, 'MAD', 'Pièce', '10 Pièce', 'https://lechantier.ma/uploads/media/d1ff47e7b704.webp', $j$["https://lechantier.ma/uploads/media/d1ff47e7b704.webp", "https://lechantier.ma/uploads/media/a6b3dc0ee28a.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/materiel-electrique/cadre-spot-aluminium", "category_fr": "Electrical supplies", "supplier_matching_status": "matched", "technical_specifications_detailed": "• CADRE SPOT EN ALUMINIUMMatière : AluminiumFinition : Blanc / Noir / Gold / GrisInstallation : EncastréeCompatibilité : Spots LEDDesign : Moderne et discretApplication : Résidentiel, commerces, bureaux et hôtels", "technical_specifications_original": "• CADRE SPOT EN ALUMINIUMMatière : AluminiumFinition : Blanc / Noir / Gold / GrisInstallation : EncastréeCompatibilité : Spots LEDDesign : Moderne et discretApplication : Résidentiel, commerces, bureaux et hôtels", "specs": "• CADRE SPOT EN ALUMINIUMMatière : AluminiumFinition : Blanc / Noir / Gold / GrisInstallation : EncastréeCompatibilité : Spots LEDDesign : Moderne et discretApplication : Résidentiel, commerces, bureaux et hôtels"}$j$::jsonb, 'https://lechantier.ma/en/produits/materiel-electrique/cadre-spot-aluminium') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDE