INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('2fc8f4cc-d2b7-56f8-bac0-ef2e44efab72'::uuid, '433c6235-ef86-54ef-885c-13b43dea1609'::uuid, 'Raille magnétiques', 'une solution d''éclairage moderne, élégante et modulable. Facile à installer, il permet de positionner et déplacer les spots selon vos besoins, tout en apportant une touche contemporaine à votre intérieur.', 'Electrical supplies', 'Eclairage', NULL, 95.0, 'MAD', 'Mètre', '15 Mètre linéaire', 'https://lechantier.ma/uploads/media/816c77af053a.webp', $j$["https://lechantier.ma/uploads/media/816c77af053a.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/materiel-electrique/raille-magnetiques", "category_fr": "Electrical supplies", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Rail magnétique LED : système d’éclairage moderne et modulable en 48 V DC, avec profilé en aluminium. Compatible avec spots et modules LED repositionnables, disponible en différentes longueurs et finitions. Idéal pour les habitations, commerces, bureaux et hôtels.", "technical_specifications_original": "• Rail magnétique LED : système d’éclairage moderne et modulable en 48 V DC, avec profilé en aluminium. Compatible avec spots et modules LED repositionnables, disponible en différentes longueurs et finitions. Idéal pour les habitations, commerces, bureaux et hôtels.", "specs": "• Rail magnétique LED : système d’éclairage moderne et modulable en 48 V DC, avec profilé en aluminium. Compatible avec spots et modules LED repositionnables, disponible en différentes longueurs et finitions. Idéal pour les habitations, commerces, bureaux et hôtels."}$j$::jsonb, 'https://lechantier.ma/en/produits/materiel-electrique/raille-magnetiques') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
