INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('10aceca6-a6e6-5817-9a3d-69bbe1e0cbf3'::uuid, '4d0f760d-7bf0-5df6-9eda-3d4e8b0547d1'::uuid, 'Porte composite pvc', '"YafZin Doors" هي شركة متخصصة في بيع الأبواب التركية، حيث توفر مجموعة متنوعة من الأبواب المصنوعة بجودة عالية وبتصاميم مميزة تجمع بين الأناقة والدقة التقنية.', 'Doors', NULL, NULL, 1300.0, 'MAD', 'm²', '5 Pièce', 'https://lechantier.ma/uploads/media/fa94bcf1cefb.webp', $j$["https://lechantier.ma/uploads/media/fa94bcf1cefb.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/menuiserie-portes/porte-composite-pvc", "category_fr": "Doors", "supplier_matching_status": "matched", "technical_specifications_detailed": null, "technical_specifications_original": null, "specs": null}$j$::jsonb, 'https://lechantier.ma/en/produits/menuiserie-portes/porte-composite-pvc') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('687a3b88-2069-5120-9a26-3874783062c6'::uuid, 'b22bf46f-53d6-5271-a13a-8606403cc486'::uuid, 'Porte en chêne', 'Porte en placage chêne européen ou américain', 'Doors', NULL, NULL, 2500.0, 'MAD', 'm²', '15 Pièce', 'https://lechantier.ma/uploads/media/e1b1bb2d9c0e.webp', $j$["https://lechantier.ma/uploads/media/e1b1bb2d9c0e.webp"]$j$::jsonb, $j$["Fès"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/menuiserie-portes/porte-en-chene", "category_fr": "Doors", "supplier_matching_status": "matched", "technical_specifications_detailed": "• La porte est habillée d’un placage en chêne, issu soit de chêne européen, réputé pour son grain fin et sa teinte claire et chaleureuse, soit de chêne américain, aux veines plus marquées et à la couleur légèrement plus soutenue. Ce placage naturel est appliqué sur un support en MDF hydrofuge ou contreplaqué, garantissant une excellente stabilité et une finition de haute qualité. Le rendu esthétique met en valeur l’aspect authentique du bois, tout en permettant diverses finitions : vernis mat, satiné ou huilé, selon les préférences. Le cadre et le chambranle peuvent être assortis en bois massif ou également plaqués pour assurer une continuité visuelle. Robuste et élégant, ce type de porte est idéal pour les intérieurs haut de gamme, apportant une touche de naturel et de raffinement.", "technical_specifications_original": "• La porte est habillée d’un placage en chêne, issu soit de chêne européen, réputé pour son grain fin et sa teinte claire et chaleureuse, soit de chêne américain, aux veines plus marquées et à la couleur légèrement plus soutenue. Ce placage naturel est appliqué sur un support en MDF hydrofuge ou contreplaqué, garantissant une excellente stabilité et une finition de haute qualité. Le rendu esthétique met en valeur l’aspect authentique du bois, tout en permettant diverses finitions : vernis mat, satiné ou huilé, selon les préférences. Le cadre et le chambranle peuvent être assortis en bois massif ou également plaqués pour assurer une continuité visuelle. Robuste et élégant, ce type de porte est idéal pour les intérieurs haut de gamme, apportant une touche de naturel et de raffinement.", "specs": "• La porte est habillée d’un placage en chêne, issu soit de chêne européen, réputé pour son grain fin et sa teinte claire et chaleureuse, soit de chêne américain, aux veines plus marquées et à la couleur légèrement plus soutenue. Ce placage naturel est appliqué sur un support en MDF hydrofuge ou contreplaqué, garantissant une excellente stabilité et une finition de haute qualité. Le rendu esthétique met en valeur l’aspect authentique du bois, tout en permettant diverses finitions : vernis mat, satiné ou huilé, selon les préférences. Le cadre et le chambranle peuvent être assortis en bois massif ou également plaqués pour assurer une continuité visuelle. Robuste et élégant, ce type de porte est idéal pour les intérieurs haut de gamme, apportant une touche de naturel et de raffinement."}$j$::jsonb, 'https://lechantier.ma/en/produits/menuiserie-portes/porte-en-chene') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('783e4338-0c3b-5573-ae82-9bd199f31cda'::uuid, 'b22bf46f-53d6-5271-a13a-8606403cc486'::uuid, 'Porte en noyer artificiel', 'Porte en noyer artificiel', 'Doors', NULL, NULL, 2500.0, 'MAD', 'm²', '15 Pièce', 'https://lechantier.ma/uploads/media/db0fd9b9ea1e.webp', $j$["https://lechantier.ma/uploads/media/db0fd9b9ea1e.webp"]$j$::jsonb, $j$["Fès"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/menuiserie-portes/porte-en-noyer-artificiel", "category_fr": "Doors", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Selon l’usage et l’environnement, les portes peuvent être fabriquées à partir de différents types de panneaux, chacun présentant des avantages spécifiques. Le panneau hydrofuge, généralement en MDF ou aggloméré traité, est particulièrement adapté aux pièces humides comme les salles de bains ou cuisines, grâce à sa résistance à l’humidité. Le panneau latté, composé d’un cadre en bois massif rempli de lattes et recouvert de parements, offre une excellente stabilité et une bonne résistance mécanique tout en étant plus léger qu’un panneau plein. Quant au contreplaqué, constitué de fines couches de bois collées en croisant les fibres, il se distingue par sa solidité et sa bonne tenue dans le temps, même en milieux légèrement humides. Ces différents matériaux permettent d’adapter les portes aux besoins esthétiques, techniques et budgétaires de chaque projet", "technical_specifications_original": "• Selon l’usage et l’environnement, les portes peuvent être fabriquées à partir de différents types de panneaux, chacun présentant des avantages spécifiques. Le panneau hydrofuge, généralement en MDF ou aggloméré traité, est particulièrement adapté aux pièces humides comme les salles de bains ou cuisines, grâce à sa résistance à l’humidité. Le panneau latté, composé d’un cadre en bois massif rempli de lattes et recouvert de parements, offre une excellente stabilité et une bonne résistance mécanique tout en étant plus léger qu’un panneau plein. Quant au contreplaqué, constitué de fines couches de bois collées en croisant les fibres, il se distingue par sa solidité et sa bonne tenue dans le temps, même en milieux légèrement humides. Ces différents matériaux permettent d’adapter les portes aux besoins esthétiques, techniques et budgétaires de chaque projet", "specs": "• Selon l’usage et l’environnement, les portes peuvent être fabriquées à partir de différents types de panneaux, chacun présentant des avantages spécifiques. Le panneau hydrofuge, généralement en MDF ou aggloméré traité, est particulièrement adapté aux pièces humides comme les salles de bains ou cuisines, grâce à sa résistance à l’humidité. Le panneau latté, composé d’un cadre en bois massif rempli de lattes et recouvert de parements, offre une excellente stabilité et une bonne résistance mécanique tout en étant plus léger qu’un panneau plein. Quant au contreplaqué, constitué de fines couches de bois collées en croisant les fibres, il se distingue par sa solidité et sa bonne tenue dans le temps, même en milieux légèrement humides. Ces différents matériaux permettent d’adapter les portes aux besoins esthétiques, techniques et budgétaires de chaque projet"}$j$::jsonb, 'https://lechantier.ma/en/produits/menuiserie-portes/porte-en-noyer-artificiel') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
