INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('9bc08785-33ed-593a-a3fb-ae88e9c03c41'::uuid, 'b22bf46f-53d6-5271-a13a-8606403cc486'::uuid, 'Porte idoplane intérieur / extérieur', 'Porte idoplane intérieur / extérieur in Morocco 2026: 1.600-2.160 MAD. Technical specifications, verified suppliers, instant quote request.', 'Doors', NULL, NULL, NULL, 'MAD', 'm²', '50 Pièce', 'https://lechantier.ma/uploads/media/64c1bdda6e61.webp', $j$["https://lechantier.ma/uploads/media/64c1bdda6e61.webp", "https://lechantier.ma/uploads/media/fa94bcf1cefb.webp", "https://lechantier.ma/uploads/media/018d3b74e854.webp", "https://lechantier.ma/uploads/media/9b53c4059a14.webp", "https://lechantier.ma/uploads/media/bfe8156f55b0.webp", "https://lechantier.ma/uploads/media/db0fd9b9ea1e.webp"]$j$::jsonb, $j$["Fès"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/menuiserie-portes/porte-idoplane-interieur-exterieur", "category_fr": "Doors", "supplier_matching_status": "matched", "technical_specifications_detailed": "• La porte isoplane est constituée d’un vantail à âme pleine ou alvéolaire, revêtu de parements en MDF pour offrir une surface lisse et résistante. Elle est habillée d’un film en PVC qui lui confère une excellente résistance à l’humidité, facilitant ainsi son entretien et la rendant idéale pour des environnements tels que les salles de bains, cuisines ou locaux techniques. Le cadre, le chambranle et le cadrage sont réalisés en bois rouge massif, reconnu pour sa robustesse et sa durabilité, assurant une bonne tenue de l’ensemble dans le temps. Cette configuration allie à la fois solidité, esthétisme et fonctionnalité, tout en répondant aux exigences d’un usage intérieur dans des conditions potentiellement humides.", "technical_specifications_original": "• La porte isoplane est constituée d’un vantail à âme pleine ou alvéolaire, revêtu de parements en MDF pour offrir une surface lisse et résistante. Elle est habillée d’un film en PVC qui lui confère une excellente résistance à l’humidité, facilitant ainsi son entretien et la rendant idéale pour des environnements tels que les salles de bains, cuisines ou locaux techniques. Le cadre, le chambranle et le cadrage sont réalisés en bois rouge massif, reconnu pour sa robustesse et sa durabilité, assurant une bonne tenue de l’ensemble dans le temps. Cette configuration allie à la fois solidité, esthétisme et fonctionnalité, tout en répondant aux exigences d’un usage intérieur dans des conditions potentiellement humides.", "specs": "• La porte isoplane est constituée d’un vantail à âme pleine ou alvéolaire, revêtu de parements en MDF pour offrir une surface lisse et résistante. Elle est habillée d’un film en PVC qui lui confère une excellente résistance à l’humidité, facilitant ainsi son entretien et la rendant idéale pour des environnements tels que les salles de bains, cuisines ou locaux techniques. Le cadre, le chambranle et le cadrage sont réalisés en bois rouge massif, reconnu pour sa robustesse et sa durabilité, assurant une bonne tenue de l’ensemble dans le temps. Cette configuration allie à la fois solidité, esthétisme et fonctionnalité, tout en répondant aux exigences d’un usage intérieur dans des conditions potentiellement humides."}$j$::jsonb, 'https://lechantier.ma/en/produits/menuiserie-portes/porte-idoplane-interieur-exterieur') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
