INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('80132e06-336d-50fc-91ae-f187afa46a0d'::uuid, '088d8da4-7888-5d58-af9b-b40de64edcaf'::uuid, 'SYSTEME DE SUSPENSION MEUBLE TRASER 6 -', 'Suspensions d''armoire invisibles TRASER-6.', 'Hand tools', NULL, NULL, 36.0, 'MAD', 'Pièce', '50 Pièce', 'https://lechantier.ma/uploads/media/919a3fa41787.webp', $j$["https://lechantier.ma/uploads/media/919a3fa41787.webp", "https://lechantier.ma/uploads/media/9e5cebdb6c9c.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/outillage-a-main/systeme-de-suspension-meuble-traser-6", "category_fr": "Hand tools", "supplier_matching_status": "matched", "technical_specifications_detailed": "• > Version anti basculement il est monté comme la suspension standard TRASER-6 et empêche tout décrochage involontaire des armoires suspendue.> Sécurité maximale. Capacité de charge nominale de 65kg par support*. Norme EN 15939 sur structure d’essai A.> Maximum de réglage et de précision, sans aucun problème. Un trou de Ø18 mm permet ’avoir accès à tous les réglages. Nos vis de réglage ne pénètrent jamais dans la partie arrière du meuble.", "technical_specifications_original": "• > Version anti basculement il est monté comme la suspension standard TRASER-6 et empêche tout décrochage involontaire des armoires suspendue.> Sécurité maximale. Capacité de charge nominale de 65kg par support*. Norme EN 15939 sur structure d’essai A.> Maximum de réglage et de précision, sans aucun problème. Un trou de Ø18 mm permet ’avoir accès à tous les réglages. Nos vis de réglage ne pénètrent jamais dans la partie arrière du meuble.", "specs": "• > Version anti basculement il est monté comme la suspension standard TRASER-6 et empêche tout décrochage involontaire des armoires suspendue.> Sécurité maximale. Capacité de charge nominale de 65kg par support*. Norme EN 15939 sur structure d’essai A.> Maximum de réglage et de précision, sans aucun problème. Un trou de Ø18 mm permet ’avoir accès à tous les réglages. Nos vis de réglage ne pénètrent jamais dans la partie arrière du meuble."}$j$::jsonb, 'https://lechantier.ma/en/produits/outillage-a-main/systeme-de-suspension-meuble-traser-6') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
